import{_ as a,o as t,c as s,a0 as r}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"指挥 ChatGPT 出方案、DeepSeek Harness 执行，一组数据能榨出好多论文","description":"昨天主要指挥 ChatGPT 和 DeepSeek Harness 干活：我整理数据提思路，ChatGPT 拟定研究方案，DeepSeek Harness 负责执行；效率真的高，同一组数据集能产出非常多的论文。","frontmatter":{"title":"指挥 ChatGPT 出方案、DeepSeek Harness 执行，一组数据能榨出好多论文","date":"2026-09-05T00:00:00.000Z","tags":["日记"],"description":"昨天主要指挥 ChatGPT 和 DeepSeek Harness 干活：我整理数据提思路，ChatGPT 拟定研究方案，DeepSeek Harness 负责执行；效率真的高，同一组数据集能产出非常多的论文。"},"headers":[],"relativePath":"posts/diary-20260905.md","filePath":"posts/diary-20260905.md","lastUpdated":1788658773000}'),n={name:"posts/diary-20260905.md"};function o(p,e,h,i,l,d){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="指挥-chatgpt-出方案、deepseek-harness-执行-一组数据能榨出好多论文" tabindex="-1">指挥 ChatGPT 出方案、DeepSeek Harness 执行，一组数据能榨出好多论文 <a class="header-anchor" href="#指挥-chatgpt-出方案、deepseek-harness-执行-一组数据能榨出好多论文" aria-label="Permalink to &quot;指挥 ChatGPT 出方案、DeepSeek Harness 执行，一组数据能榨出好多论文&quot;">​</a></h1><p>昨天（9月5日）这篇补一下，忘了写嘿嘿。昨天没怎么亲自动手，主要干的是<strong>指挥</strong>的活儿——指挥两个 AI 给我打工 😎。</p><h2 id="我的角色-整理数据-提思路" tabindex="-1">我的角色：整理数据 + 提思路 <a class="header-anchor" href="#我的角色-整理数据-提思路" aria-label="Permalink to &quot;我的角色：整理数据 + 提思路&quot;">​</a></h2><p>我这边负责的，是<strong>把数据整理好</strong>，然后<strong>提出一个初步的思路</strong>。</p><p>说白了就是：我知道自己手里有什么料、大概想讲个什么故事，但具体怎么设计分析、怎么拆成一套能站得住的方案，这活儿交出去。</p><p>这一步其实是最该人干的——数据对不对、思路靠不靠谱，得我来把关。剩下的执行，才轮到它们上。</p><h2 id="分工-chatgpt-定方案-harness-执行" tabindex="-1">分工：ChatGPT 定方案，Harness 执行 <a class="header-anchor" href="#分工-chatgpt-定方案-harness-执行" aria-label="Permalink to &quot;分工：ChatGPT 定方案，Harness 执行&quot;">​</a></h2><p>昨天的流水线大概是这样跑的：</p><ol><li><strong>ChatGPT 来拟定研究方案</strong> 🧠——我把数据和初步想法丢过去，它帮我把研究设计捋出来：用什么方法、跑哪几步、怎么验证、结论往哪儿落。这一步是&quot;出脑子&quot;。</li><li><strong>DeepSeek Harness 来执行</strong> ⚙️——方案定好，交给 Harness 去跑分析、出图、出结果。这一步是&quot;出力气&quot;。</li></ol><p>一个管想、一个管干，我在中间当包工头。这分工跑起来之后，我发现自己真正动手写代码的时间少了一大截，精力全花在&quot;判断对不对&quot;上——这才是该花精力的地方。</p><h2 id="感受-效率真的高" tabindex="-1">感受：效率真的高 <a class="header-anchor" href="#感受-效率真的高" aria-label="Permalink to &quot;感受：效率真的高&quot;">​</a></h2><p>最大的体会是：<strong>效率真的高</strong> 🚀。</p><p>而且高得不只是一点半点——<strong>同一组数据集，可以产出非常多的论文</strong>。以前一组数据挖一两个角度就觉得差不多了，现在方案拆得细、执行跑得快，换个切入点又是一篇。数据还是那些数据，但产出密度完全不一样了。</p><p>有种&quot;黑心资本家&quot;把流水线开起来的感觉，机器不停转，我在旁边验收嘿嘿。</p><h2 id="实话实说-harness-还是有点笨" tabindex="-1">实话实说：Harness 还是有点笨 <a class="header-anchor" href="#实话实说-harness-还是有点笨" aria-label="Permalink to &quot;实话实说：Harness 还是有点笨&quot;">​</a></h2><p>当然也不是全无槽点——<strong>DeepSeek Harness 还是有点笨的</strong> 😂。</p><p>它执行具体任务还行，但让它自己拿主意就容易跑偏，理解复杂意图的时候也会犯轴，时不时需要我把话说得更直白一点。</p><p><strong>但是有 ChatGPT 指导其工作，还是可以的</strong>。ChatGPT 把方案写得足够细、把步骤拆得足够清楚，Harness 照着做就不太会出岔子。等于给一个执行力强但脑子不太够用的工人，配了个细致的工头——这组合意外地好用。</p><p>所以结论是：<strong>执行工作还是挺有效率的</strong>，前提是上面有人把它该干什么讲明白。</p><h2 id="就这样-加油" tabindex="-1">就这样，加油 <a class="header-anchor" href="#就这样-加油" aria-label="Permalink to &quot;就这样，加油&quot;">​</a></h2><p>这套&quot;人出数据+思路 → ChatGPT 出方案 → Harness 执行&quot;的流水线，昨天算是彻底跑顺了。后面几篇论文应该都能照这个模式推。</p><p>继续加油 💪！</p>',22)])])}const g=a(n,[["render",o]]);export{u as __pageData,g as default};
